namespace ghidra.app.plugin.core.misc;

using static org.junit.Assert;






using org.junit;
using org.junit;

using docking;
using docking.options.editor;
using docking.options.editor;
using docking.widgets.tree;
using ghidra.framework.options;
using ghidra.test;

public class PropertyEditorTest : AbstractGhidraHeadedIntegrationTest {

	private OptionsDialog dialog;

	/* @After */
	public void tearDown()
    {
		if (dialog != null) {
			close(dialog);
		}
		waitForSwing();
	}

	private OptionsDialog showEditor(Options options) {
		OptionsDialog dialogComponent =
			new OptionsDialog("Test Properties", "Properties", new Options[] { options }, null);
		runSwing(() => DockingWindowManager.showDialog(dialogComponent), false);

		OptionsDialog editorDialog = waitForDialogComponent(typeof(OptionsDialog));
		waitForSwing();
		waitForOptionsTree(dialogComponent);
		return editorDialog;
	}

	private void waitForOptionsTree(OptionsDialog optionsDialog) {
		object optionsPanel = getInstanceField("panel", optionsDialog);
		GTree tree = (GTree) getInstanceField("gTree", optionsPanel);
		waitForTree(tree);
	}

	private Component findPairedComponent(string labelText) {
		JComponent component = dialog.getComponent();
		return runSwing(() => doFindPairedComponent(component, labelText));
	}

	private Component doFindPairedComponent(Container container, string labelText) {
		Component[] c = container.getComponents();
		for (int i = 0; i < c.length; i++) {
			if (c[i] is JLabel) {
				if (((JLabel) c[i]).getText().equals(labelText)) {
					return c[i + 1];
				}
			}
			if (c[i] is Container) {
				Component comp = doFindPairedComponent((Container) c[i], labelText);
				if (comp != null) {
					return comp;
				}
			}
		}
		return null;

	}

	private void selectTextField(JTextField field) {
		runSwing(() => field.selectAll(), true);
	}

	/* @Test */
	public void testInt()
    {

		Options options = new ToolOptions("Test");
		options.registerOption("TestInt", int.MaxValue, null, "Int");

		dialog = showEditor(options);

		Component editor = findPairedComponent("TestInt");
		assertNotNull("Could not find editor component", editor);
		assertEquals(typeof(PropertyText), editor.GetType());
		PropertyText textField = (PropertyText) editor;
		assertEquals(Integer.toString(int.MaxValue), textField.getText());

		selectTextField(textField);

		triggerText(textField, Integer.toString(int.MinValue));

		pressButtonByText(dialog, "OK");

		assertEquals(int.MinValue, options.getInt("TestInt", 0));
	}

